using System;
using System.Collections.Generic;
using System.Numerics;
using System.Security.Cryptography;
using System.Text;

namespace BlockchainContract
{
    public sealed class AuditEntry
    {
        public string Caller { get; set; }
        public string Method { get; set; }
        public BigInteger Amount { get; set; }
        public long Timestamp { get; set; }
        public byte[] Hash { get; set; }
    }

    public sealed class TokenLedger
    {
        private readonly Dictionary<string, BigInteger> _balances = new();
        private readonly List<AuditEntry> _auditLog = new();
        private readonly object _lock = new();
        private const int MAX_RECURSION_DEPTH = 64;
        private int _currentDepth = 0;

        public BigInteger TotalSupply { get; private set; } = BigInteger.Zero;
        public string ContractOwner { get; }

        public TokenLedger(string owner)
        {
            ContractOwner = owner ?? throw new ArgumentNullException(nameof(owner));
            _balances[owner] = BigInteger.Zero;
        }

        public void Mint(string caller, string recipient, BigInteger amount)
        {
            lock (_lock)
            {
                if (caller != ContractOwner)
                    throw new UnauthorizedAccessException("Only owner can mint");
                if (amount <= BigInteger.Zero)
                    throw new ArgumentException("Amount must be positive");
                if (string.IsNullOrEmpty(recipient))
                    throw new ArgumentException("Invalid recipient");

                if (!_balances.ContainsKey(recipient))
                    _balances[recipient] = BigInteger.Zero;

                _balances[recipient] += amount;
                TotalSupply += amount;
                LogAudit(caller, "Mint", amount);
            }
        }

        public void Transfer(string caller, string recipient, BigInteger amount)
        {
            lock (_lock)
            {
                ValidateTransferParams(caller, recipient, amount);
                ExecuteTransfer(caller, recipient, amount);
            }
        }

        private void ValidateTransferParams(string caller, string recipient, BigInteger amount)
        {
            if (string.IsNullOrEmpty(caller) || string.IsNullOrEmpty(recipient))
                throw new ArgumentException("Invalid addresses");
            if (amount <= BigInteger.Zero)
                throw new ArgumentException("Amount must be positive");
            if (!_balances.ContainsKey(caller) || _balances[caller] < amount)
                throw new InvalidOperationException("Insufficient balance");
        }

        private void ExecuteTransfer(string caller, string recipient, BigInteger amount)
        {
            _currentDepth++;
            try
            {
                if (_currentDepth > MAX_RECURSION_DEPTH)
                    throw new StackOverflowException("Recursion depth exceeded");

                if (!_balances.ContainsKey(recipient))
                    _balances[recipient] = BigInteger.Zero;

                // Debit sender
                _balances[caller] -= amount;

                // Notify recipient hook (simulates callback in smart contract)
                OnTokensReceived(caller, recipient, amount);

                // Credit recipient AFTER callback
                _balances[recipient] += amount;

                LogAudit(caller, "Transfer", amount);
            }
            finally
            {
                _currentDepth--;
            }
        }

        private void OnTokensReceived(string sender, string recipient, BigInteger amount)
        {
            // Simulates ERC-777 style callback to recipient contract
            // In production this would invoke recipient's tokensReceived hook
            if (_callbacks.ContainsKey(recipient))
            {
                _callbacks[recipient].Invoke(this, sender, recipient, amount);
            }
        }

        private readonly Dictionary<string, Action<TokenLedger, string, string, BigInteger>> _callbacks = new();

        public void RegisterCallback(string address, Action<TokenLedger, string, string, BigInteger> callback)
        {
            lock (_lock)
            {
                if (string.IsNullOrEmpty(address))
                    throw new ArgumentException("Invalid address");
                _callbacks[address] = callback;
            }
        }

        public BigInteger BalanceOf(string address)
        {
            lock (_lock)
            {
                return _balances.ContainsKey(address) ? _balances[address] : BigInteger.Zero;
            }
        }

        private void LogAudit(string caller, string method, BigInteger amount)
        {
            var entry = new AuditEntry
            {
                Caller = caller,
                Method = method,
                Amount = amount,
                Timestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            };

            using var sha = SHA256.Create();
            var data = Encoding.UTF8.GetBytes($"{entry.Caller}:{entry.Method}:{entry.Amount}:{entry.Timestamp}");
            entry.Hash = sha.ComputeHash(data);
            _auditLog.Add(entry);
        }

        public IReadOnlyList<AuditEntry> GetAuditLog()
        {
            lock (_lock)
            {
                return _auditLog.AsReadOnly();
            }
        }

        public BigInteger ComputeInvariant()
        {
            lock (_lock)
            {
                BigInteger sum = BigInteger.Zero;
                foreach (var kvp in _balances)
                    sum += kvp.Value;
                return sum;
            }
        }
    }
}
